(() => {
  const box = el => el.getBoundingClientRect();
  const hit = (a, b) => a.left < b.right - 0.5 && b.left < a.right - 0.5 && a.top < b.bottom - 0.5 && b.top < a.bottom - 0.5;
  const bad = [];
  const rows = [...document.querySelectorAll('[data-testid="runs-list"] .dsc-run')];
  for (const row of rows) {
    const rb = box(row);
    const parts = [...row.querySelectorAll('.dsc-run-glyph, .dsc-run-left .k-badge, .dsc-cov, .dsc-run-text > b, .dsc-draft-name, .dsc-run-meta, .dsc-run-mid > .dsc-run-line, .dsc-run-text > .dsc-run-line, .dsc-run-actions .k-btn, .dsc-run-remove:not(.ghost), .dsc-pick:not(.ghost), .dsc-run-report')].filter(e => box(e).width > 0);
    for (let i = 0; i < parts.length; i++) {
      const a = box(parts[i]);
      if (a.right > rb.right + 0.5 || a.left < rb.left - 0.5 || a.bottom > rb.bottom + 0.5 || a.top < rb.top - 0.5) bad.push(row.dataset.testid + ': ' + parts[i].className + ' leaves the box');
      for (let j = i + 1; j < parts.length; j++) {
        if (parts[i].contains(parts[j]) || parts[j].contains(parts[i])) continue;
        if (hit(a, box(parts[j]))) bad.push(row.dataset.testid + ': ' + parts[i].className + ' x ' + parts[j].className);
      }
    }
    const L = row.querySelector('.dsc-run-left'), M = row.querySelector('.dsc-run-mid'), R = row.querySelector('.dsc-run-right');
    if (!L || !M || !R) bad.push(row.dataset.testid + ': not three columns');
    else if (box(L).right > box(M).left + 0.5 || box(M).right > box(R).left + 0.5) bad.push(row.dataset.testid + ': columns overlap');
    const name = row.querySelector('.dsc-run-text > b, .dsc-draft-name b');
    if (name && box(name).width < 60) bad.push(row.dataset.testid + ': name only ' + Math.round(box(name).width) + ' px');
    const rep = row.querySelector('[data-testid^="report-"]');
    if (rep && (rep.textContent.trim() !== '' || rep.getAttribute('aria-label') !== 'Report' || rep.getAttribute('title') !== 'Report')) bad.push(row.dataset.testid + ': the Report button is not the bare icon titled Report');
    const cov = row.querySelector('.dsc-cov-n'), fact = row.querySelector('.dsc-run-line');
    if (cov && fact && getComputedStyle(cov).color === getComputedStyle(fact).color) bad.push(row.dataset.testid + ': the ch count is grey like the facts');
  }
  const list = document.querySelector('[data-testid="runs-list"]');
  list.dataset.nightGeometry = !rows.length ? 'empty' : bad.length ? 'bad' : 'ok';
  list.dataset.nightGeometryDetail = bad.slice(0, 6).join(' | ');
})()

