(() => {
  const page = document.querySelector('[data-testid="discovery-seed-page"]') || document.body;
  const card = document.querySelector('[data-testid="cut-card"]');
  if (!card) { page.dataset.nightCut = 'no-preview'; return }
  const cb = card.getBoundingClientRect(), svg = card.querySelector('[data-testid="cut-histogram"] svg');
  const bad = [];
  if (svg) { const sb = svg.getBoundingClientRect(); for (const t of svg.querySelectorAll('text')) { const b = t.getBoundingClientRect(); if (b.width === 0) continue; if (b.left < Math.max(sb.left, cb.left) - 0.5 || b.right > Math.min(sb.right, cb.right) + 0.5) bad.push('"' + t.textContent.slice(0, 30) + '" is cut at ' + (b.left < sb.left ? 'the left' : 'the right')) } }
  for (const el of card.querySelectorAll('p, .k-btn, [data-testid="param-cut-line"]')) { const b = el.getBoundingClientRect(); if (b.width && (b.left < cb.left - 0.5 || b.right > cb.right + 0.5)) bad.push(el.className + ' leaves the card') }
  page.dataset.nightCut = bad.length ? 'bad' : 'ok'; page.dataset.nightCutDetail = bad.slice(0, 4).join(' | ');
})()

(() => {
  const page = document.querySelector('[data-testid="discovery-seed-page"]') || document.body;
  const card = document.querySelector('[data-testid="seed-keep-card"]');
  if (!card) { page.dataset.nightKeep = 'no-preview'; return }
  const cb = card.getBoundingClientRect(), bad = [];
  const hit = (a, b) => a.left < b.right - 0.5 && b.left < a.right - 0.5 && a.top < b.bottom - 0.5 && b.top < a.bottom - 0.5;
  for (const el of card.querySelectorAll(':scope > :not(.dsc-card-head)')) { const b = el.getBoundingClientRect(); if (b.width && (b.left < cb.left + 8 || b.right > cb.right - 8)) bad.push(el.className + ' sits against the border') }
  for (const way of card.querySelectorAll('.dsc-keep-way, .dsc-keep-run, .dsc-keep-save')) {
    const kids = [...way.children].filter(k => k.getBoundingClientRect().width > 0 && !k.classList.contains('k-spacer'));
    for (let i = 0; i < kids.length; i++) for (let j = i + 1; j < kids.length; j++) if (hit(kids[i].getBoundingClientRect(), kids[j].getBoundingClientRect())) bad.push(way.className + ': ' + kids[i].className + ' x ' + kids[j].className);
    for (const b of way.querySelectorAll('.k-btn')) if (b.scrollWidth > b.clientWidth + 1) bad.push('a button is squished: ' + b.textContent.trim());
  }
  page.dataset.nightKeep = bad.length ? 'bad' : 'ok'; page.dataset.nightKeepDetail = bad.slice(0, 4).join(' | ');
})()

(() => {
  const bar = document.querySelector('[data-testid="map-top-scroll"]'), wrap = document.querySelector('[data-testid="map-wrap"]');
  const bad = [];
  if (!bar || !wrap) { (wrap || document.body).dataset.nightTop = 'bad'; return }
  const ds = wrap.querySelector('th.ds');
  if (ds && bar.getBoundingClientRect().bottom > ds.getBoundingClientRect().top + 0.5) bad.push('the bar is not above the dataset names');
  const overflow = wrap.scrollWidth > wrap.clientWidth + 1;
  if (overflow) {
    if (Math.abs(wrap.scrollLeft - bar.scrollLeft) > 1 || wrap.scrollLeft < 1) bad.push('the table did not follow the top bar (' + wrap.scrollLeft + ' vs ' + bar.scrollLeft + ')');
    const lab = wrap.querySelector('th.dsc-map-rowlabel');
    if (lab && Math.abs(lab.getBoundingClientRect().left - wrap.getBoundingClientRect().left) > 1) bad.push('the algorithm names scrolled away');
  }
  wrap.scrollLeft = 40;
  wrap.dataset.nightTopFirst = bad.join(' | ') || 'ok';
  wrap.dataset.nightOverflow = overflow ? '1' : '0';
})()

(() => {
  const bar = document.querySelector('[data-testid="map-top-scroll"]'), wrap = document.querySelector('[data-testid="map-wrap"]');
  if (!bar || !wrap) return;
  const bad = wrap.dataset.nightTopFirst === 'ok' ? [] : [wrap.dataset.nightTopFirst];
  if (wrap.dataset.nightOverflow === '1' && Math.abs(bar.scrollLeft - wrap.scrollLeft) > 1) bad.push('the top bar did not follow the table');
  wrap.scrollLeft = 0;
  wrap.dataset.nightTop = bad.length ? 'bad' : 'ok'; wrap.dataset.nightTopDetail = bad.join(' | ');
})()
